import{c as a,Q as n,j as e,m as t}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"GetSocVersion","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetSocVersion","slug":"getsocversion"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值","slug":"返回值"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/平台信息获取/PlatformAscendC/GetSocVersion.md","filePath":"api/Utils-API/平台信息获取/PlatformAscendC/GetSocVersion.md"}'),i={name:"api/Utils-API/平台信息获取/PlatformAscendC/GetSocVersion.md"};function o(l,s,r,p,c,d){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="getsocversion" tabindex="-1">GetSocVersion <a class="header-anchor" href="#getsocversion" aria-label="Permalink to &quot;GetSocVersion&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>获取当前硬件平台版本型号。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SocVersion GetSocVersion(void) const</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p>无</p><h2 id="返回值" tabindex="-1">返回值 <a class="header-anchor" href="#返回值" aria-label="Permalink to &quot;返回值&quot;">​</a></h2><p>当前硬件平台版本型号的枚举类。该枚举类和AI处理器型号的对应关系请通过CANN软件安装后文件存储路径下include/tiling/platform/platform_ascendc.h头文件获取。</p><p>AI处理器的型号请通过如下方式获取：</p><ul><li><p>针对如下产品：在安装AI处理器的服务器执行<strong>npu-smi info</strong>命令进行查询，获取<strong>Name</strong>信息。实际配置值为AscendName，例如<strong>Name</strong>取值为_xxxyy_，实际配置值为Ascend_xxxyy_。</p><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p><p>Atlas 200I/500 A2 推理产品</p><p>Atlas 推理系列产品</p><p>Atlas 训练系列产品</p></li><li><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，在安装AI处理器的服务器执行<strong>npu-smi info -t board -i <strong><em>id</em></strong> -c <strong>_chip_id_命令进行查询，获取</strong>Chip Name</strong>和<strong>NPU Name</strong>信息，实际配置值为Chip Name_NPU Name。例如<strong>Chip Name</strong>取值为Ascend_xxx_，<strong>NPU Name</strong>取值为1234，实际配置值为Ascend_xxx____1234。其中：</p><ul><li>id：设备id，通过<strong>npu-smi info -l</strong>命令查出的NPU ID即为设备id。</li><li>chip_id：芯片id，通过<strong>npu-smi info -m</strong>命令查出的Chip ID即为芯片id。</li></ul></li><li><p>针对Ascend 950PR/Ascend 950DT，在安装AI处理器的服务器执行<strong>npu-smi info -t board -i <strong>_id_命令进行查询，获取</strong>Chip Name</strong>和<strong>NPU Name</strong>信息，实际配置值为Chip Name_NPU Name。例如<strong>Chip Name</strong>取值为Ascend_xxx_，<strong>NPU Name</strong>取值为1234，实际配置值为Ascend_xxx____1234。</p><p>其中，id为设备id，通过<strong>npu-smi info -l</strong>命令查出的NPU ID即为设备id。</p></li></ul><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>为了满足算子二进制复用，使用Atlas A3 训练系列产品/Atlas A3 推理系列产品时，调用GetSocVersion接口返回的枚举值与Atlas A2 训练系列产品/Atlas A2 推理系列产品相同；如果需要区分，可使用接口aclrtGetSocName接口。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ge::graphStatus TilingXXX(gert::TilingContext* context) {</span></span>
<span class="line"><span>    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>    auto socVersion = ascendcPlatform.GetSocVersion();</span></span>
<span class="line"><span>    // 根据所获得的版本型号自行设计Tiling策略</span></span>
<span class="line"><span>    // ASCENDXXX请替换为实际的版本型号</span></span>
<span class="line"><span>    if (socVersion == platform_ascendc::SocVersion::ASCENDXXX) {</span></span>
<span class="line"><span>        // ...</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return ret;</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,15)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
